await p.goto(B+'/parks'); await p.waitForSelector('.park-pin'); await sleep(1500);
const rects=()=>p.evaluate(()=>[...document.querySelectorAll('.park-pin')].map(e=>{const r=e.getBoundingClientRect();return [e.getAttribute('aria-label'),r.x,r.y]}));
const zs=()=>p.evaluate(()=>{const z=[...document.querySelectorAll('.leaflet-tile-pane img')].map(i=>i.src.match(/\/(\d+)\/\d+\/\d+/)?.[1]); const c={};z.forEach(x=>c[x]=(c[x]||0)+1);return c});
const cmp=(a,b)=>{let m=0; a.forEach((r,i)=>{m=Math.max(m,Math.abs(r[1]-b[i][1]),Math.abs(r[2]-b[i][2]))}); return m.toFixed(2)};
const first=await rects(); console.log('first z',await zs());
await p.click('a[href="/parks/prospect-park"]'); await sleep(1500);
const sel=await p.evaluate(()=>{const e=document.querySelector('.park-pin.is-selected');const r=e.getBoundingClientRect();const m=document.querySelector('.leaflet-container').getBoundingClientRect();return {label:e.getAttribute('aria-label'),x:r.x+r.width/2,y:r.y+r.height/2,mapCenter:[m.x+m.width/2,m.y+m.height/2]}});
console.log('selected',sel,'z',await zs());
await p.click('a[href="/parks"][aria-label="Back to parks"]'); await sleep(600);
console.log('after back maxdiff',cmp(first,await rects()),'z',await zs());
// wheel zoom
const mb=await p.evaluate(()=>{const m=document.querySelector('.leaflet-container').getBoundingClientRect();return [m.x+m.width/2,m.y+m.height/2]});
await p.mouse.move(mb[0]+50,mb[1]+30); await p.mouse.wheel(0,-600); await sleep(500);
const zr=await rects(); console.log('after wheel diff vs first',cmp(first,zr),'z',await zs());
await p.click('button[aria-label="Recenter map"]'); await sleep(600);
console.log('after recenter maxdiff',cmp(first,await rects()),'z',await zs());
// in flight
await p.evaluate(()=>{const c=document.querySelector('.leaflet-container');const r=c.getBoundingClientRect();
 c.dispatchEvent(new WheelEvent('wheel',{deltaY:-600,clientX:r.x+r.width/2+80,clientY:r.y+r.height/2+40,bubbles:true,cancelable:true}));
 document.querySelector('button[aria-label="Recenter map"]').click();});
await sleep(600);
console.log('inflight maxdiff',cmp(first,await rects()),'z',await zs());
// also wheel->(no wait) then recenter after 100ms
await p.mouse.move(mb[0]+50,mb[1]+30); await p.mouse.wheel(0,600); await sleep(100); await p.click('button[aria-label="Recenter map"]'); await sleep(800);
console.log('wheel-out,100ms,recenter',cmp(first,await rects()),'z',await zs());
