for(let i=0;i<40;i++){await p.keyboard.press('Tab'); const a=await p.evaluate(()=>document.activeElement.classList.contains('park-pin')&&document.activeElement.getAttribute('aria-label')); if(a){hit=a;break;}}
console.log('tabbed to pin',hit);
