await p.keyboard.press('Space'); await sleep(1200);
console.log('space ->',await p.evaluate(()=>location.pathname),'scroll',before,await p.evaluate(()=>[scrollX,scrollY,document.scrollingElement.scrollTop,document.querySelector('main').scrollTop]));
// 8 reduced motion
const c2=await br.newContext({viewport:{width:1280,height:800},reducedMotion:'reduce'});
const q=await c2.newPage();
await q.goto(B+'/parks'); await q.waitForSelector('.park-pin'); await sleep(1200);
const pos=()=>q.evaluate(()=>[...document.querySelectorAll('.park-pin')].slice(0,3).map(e=>{const r=e.getBoundingClientRect();return [Math.round(r.x),Math.round(r.y)]}));
for(const id of ['prospect-park','highland-dog-park']){
 await q.click(`a[href="/parks/${id}"]`); await sleep(20); const a=await pos(); await sleep(300); const b=await pos(); await sleep(600);
 console.log('RM',id,JSON.stringify(a),JSON.stringify(b));
 await q.click('a[aria-label="Back to parks"]'); await sleep(900);
}
// select another directly from details
await q.click(`a[href="/parks/prospect-park"]`); await sleep(1200);
await q.goto(B+'/parks/prospect-park'); await sleep(1200);
// compare with normal motion for contrast
const n=await p.goto(B+'/parks'); await sleep(1200);
await p.click('a[href="/parks/highland-dog-park"]'); await sleep(20);
const na=await p.evaluate(()=>{const r=document.querySelector('.park-pin').getBoundingClientRect();return [Math.round(r.x),Math.round(r.y)]}); await sleep(300);
const nb=await p.evaluate(()=>{const r=document.querySelector('.park-pin').getBoundingClientRect();return [Math.round(r.x),Math.round(r.y)]});
console.log('normal motion contrast',na,nb);
console.log(errs); await br.close();
